create extension if not exists pgcrypto;
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,display_name text,role text not null default 'editor',is_active boolean not null default true,created_at timestamptz default now());
create or replace function public.is_kpa_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admin_users where user_id=auth.uid() and is_active=true);$$;
create table if not exists public.news_articles(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,excerpt text,content text,category text default 'School',image_url text,status text not null default 'draft' check(status in('draft','published','archived')),featured boolean default false,published_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.announcements(id uuid primary key default gen_random_uuid(),title text not null,message text not null,link_url text,priority integer default 10,is_active boolean default true,starts_at timestamptz,ends_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.admission_applications(id uuid primary key default gen_random_uuid(),reference_number text not null unique,student_first_name text not null,student_last_name text not null,student_other_names text,date_of_birth date,gender text,nationality text,state_of_origin text,current_school text,current_class text,applying_for_class text not null,academic_session text not null,parent_name text not null,relationship_to_student text,parent_phone text not null,parent_whatsapp text,parent_email text not null,residential_address text not null,occupation text,emergency_contact_name text,emergency_contact_phone text,previous_school_notes text,support_information text,how_heard text,parent_message text,consent boolean not null default false,status text not null default 'new' check(status in('new','review','contacted','assessment','offered','accepted','declined','closed')),source text default 'website',internal_note text,reviewed_by uuid references auth.users(id),created_at timestamptz default now(),updated_at timestamptz default now());
alter table public.admin_users enable row level security;alter table public.news_articles enable row level security;alter table public.announcements enable row level security;alter table public.admission_applications enable row level security;
create policy "public published news" on public.news_articles for select to anon,authenticated using(status='published' and published_at<=now());
create policy "public active announcements" on public.announcements for select to anon,authenticated using(is_active=true and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now()));
create policy "public admission insert" on public.admission_applications for insert to anon,authenticated with check(consent=true and status='new');
create policy "admins admin_users" on public.admin_users for all to authenticated using(public.is_kpa_admin()) with check(public.is_kpa_admin());
create policy "admins news" on public.news_articles for all to authenticated using(public.is_kpa_admin()) with check(public.is_kpa_admin());
create policy "admins announcements" on public.announcements for all to authenticated using(public.is_kpa_admin()) with check(public.is_kpa_admin());
create policy "admins admissions" on public.admission_applications for all to authenticated using(public.is_kpa_admin()) with check(public.is_kpa_admin());
insert into storage.buckets(id,name,public) values('website-media','website-media',true) on conflict(id) do update set public=true;
create policy "public media read" on storage.objects for select to anon,authenticated using(bucket_id='website-media');
create policy "admin media insert" on storage.objects for insert to authenticated with check(bucket_id='website-media' and public.is_kpa_admin());
create policy "admin media update" on storage.objects for update to authenticated using(bucket_id='website-media' and public.is_kpa_admin()) with check(bucket_id='website-media' and public.is_kpa_admin());
create policy "admin media delete" on storage.objects for delete to authenticated using(bucket_id='website-media' and public.is_kpa_admin());
create index if not exists idx_news_status on public.news_articles(status,published_at desc);
create index if not exists idx_ann_active on public.announcements(is_active,priority desc);
create index if not exists idx_adm_status on public.admission_applications(status,created_at desc);
